export function chunk(input, size) {
  if (!Array.isArray(input)) throw new TypeError('input must be an array');
  if (!Number.isInteger(size) || size < 1) {
    throw new RangeError('size must be an integer of at least 1');
  }
  const out = [];
  for (let i = 0; i < input.length; i += size) out.push(input.slice(i, i + size));
  return out;
}
